CREATE TABLE _rowva_workspace(id TEXT PRIMARY KEY,name TEXT NOT NULL,schema_revision INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE _rowva_objects(id TEXT PRIMARY KEY,display_name TEXT NOT NULL,key TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,schema_revision INTEGER NOT NULL);
CREATE TABLE _rowva_fields(id TEXT PRIMARY KEY,object_id TEXT NOT NULL REFERENCES _rowva_objects(id) ON DELETE CASCADE,display_name TEXT NOT NULL,key TEXT NOT NULL,kind_json TEXT NOT NULL,required INTEGER NOT NULL,unique_flag INTEGER NOT NULL,position INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,schema_revision INTEGER NOT NULL,UNIQUE(object_id,key));
CREATE TABLE _rowva_actors(id TEXT PRIMARY KEY,actor_type TEXT NOT NULL,display_name TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE _rowva_operations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,actor_id TEXT NOT NULL,actor_type TEXT NOT NULL,actor_display_name TEXT NOT NULL,kind TEXT NOT NULL,mode TEXT NOT NULL,status TEXT NOT NULL,reason TEXT,idempotency_key TEXT,request_json TEXT NOT NULL,result_json TEXT,error_json TEXT,created_at TEXT NOT NULL,committed_at TEXT,base_schema_revision INTEGER NOT NULL,resulting_schema_revision INTEGER,UNIQUE(actor_id,idempotency_key));
CREATE TABLE _rowva_operation_changes(id INTEGER PRIMARY KEY AUTOINCREMENT,operation_id TEXT NOT NULL REFERENCES _rowva_operations(id),object_id TEXT NOT NULL,record_id TEXT,field_id TEXT,before_json TEXT,after_json TEXT);
